import{_ as a,o as t,c as n,a0 as r}from"./chunks/framework.D7EjqxMK.js";const g=JSON.parse('{"title":"Plan-and-Execute 架构","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/03_高级模式/02_Plan_and_Execute架构.md","filePath":"06-agent/03_高级模式/02_Plan_and_Execute架构.md"}'),l={name:"06-agent/03_高级模式/02_Plan_and_Execute架构.md"};function o(i,e,s,c,_,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="plan-and-execute-架构" tabindex="-1">Plan-and-Execute 架构 <a class="header-anchor" href="#plan-and-execute-架构" aria-label="Permalink to &quot;Plan-and-Execute 架构&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块三 · 03_高级模式 · 第 2 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：ReAct 模式</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>Plan-and-Execute</strong> 是区分「玩具级」与「生产级」Agent 的核心分水岭。<a href="https://jishuzhan.net/article/2046065875397181442" target="_blank" rel="noreferrer">来源: 技术栈 - Planning Agent 架构深度解析</a></p><p>ReAct 适合短任务（每一步决策都是 LLM 实时生成），但长任务需要<strong>先规划后执行</strong>，避免在每一步都调用 LLM（成本高、容易出错）。</p><hr><h2 id="_2-两种架构对比" tabindex="-1">2. 两种架构对比 <a class="header-anchor" href="#_2-两种架构对比" aria-label="Permalink to &quot;2. 两种架构对比&quot;">​</a></h2><p>| 架构 | 说明 | 适用场景 | |--|-|--|- | | <strong>ReAct</strong> | 每步推理 + 每步执行 | 短任务、简单流程 | | <strong>Plan-and-Execute</strong> | 先生成完整计划，再逐步执行 | 长任务、复杂流程 | | <strong>Plan→Commit</strong> | LLM 规划 + 系统确定性执行 | 生产级 Agent |</p><hr><h2 id="_3-参考资料" tabindex="-1">3. 参考资料 <a class="header-anchor" href="#_3-参考资料" aria-label="Permalink to &quot;3. 参考资料&quot;">​</a></h2><ul><li><a href="https://jishuzhan.net/article/2046065875397181442" target="_blank" rel="noreferrer">Planning Agent 架构深度解析 (技术栈)</a></li><li><a href="https://jishuzhan.net/article/2046050411493261314" target="_blank" rel="noreferrer">从 ReAct 到 Plan-and-Execute (技术栈)</a></li><li><a href="https://blogs.utilia.dev/planner-executor-pattern-architecting-reliable-agents" target="_blank" rel="noreferrer">Planner + Executor Pattern (Utilia)</a></li><li><a href="https://notes.muthu.co/2026/03/receding-horizon-planning-and-plan-commitment-in-agent-reasoning-loops/" target="_blank" rel="noreferrer">Receding Horizon Planning and Plan Commitment (notes.muthu.co)</a></li></ul>',12)])])}const u=a(l,[["render",o]]);export{g as __pageData,u as default};
